#nullable enable

using System.Linq;
using Catamailer.Domain;
using Catamailer.Migrator.Seeding;
using Xunit;

namespace Catamailer.Migrator.Tests
{
    /// <summary>
    /// Classe de test validant l'initialisation en dur des règles complexes issues du code historique VBA.
    /// </summary>
    public class LegacyExecutionRuleSeederTests
    {
        [Fact]
        public void GetHardcodedExecutionRules_ShouldReturnAll13LegacyVbaRules_WithCorrectCriteriaAndActions()
        {
            // Arrange
            var seeder = new LegacyExecutionRuleSeeder();

            // Act
            var rules = seeder.GetHardcodedExecutionRules().ToList();

            // Assert : 6 règles métier + 7 règles de déplacement = 13 règles
            Assert.Equal(13, rules.Count);

            // 1. Qualif CEDA - Actions demandées
            var qualifActions = rules.Single(r => r.Name == "Qualif CEDA - Actions demandées");
            Assert.Single(qualifActions.RootNode.Criteria);
            Assert.Equal(MailField.Subject, qualifActions.RootNode.Criteria[0].Field);
            Assert.Equal(MatchOperator.RegexMatch, qualifActions.RootNode.Criteria[0].Operator);
            Assert.Equal(@"^\[CEDA\] : Actions demandées:", qualifActions.RootNode.Criteria[0].Value);
            Assert.Equal(3, qualifActions.Actions.Count);
            Assert.Equal(ActionType.AddCategory, qualifActions.Actions[0].Type);
            Assert.Equal("DAMSI-DA-QUALIF CEDA", qualifActions.Actions[0].Parameter);
            Assert.Equal(ActionType.SetImportance, qualifActions.Actions[1].Type);
            Assert.Equal("Haute", qualifActions.Actions[1].Parameter);
            Assert.Equal(ActionType.FlagToday, qualifActions.Actions[2].Type);

            // 2. Qualif CEDA - Compte rendu
            var qualifCr = rules.Single(r => r.Name == "Qualif CEDA - Compte rendu");
            Assert.Single(qualifCr.RootNode.Criteria);
            Assert.Equal(@"^\[CEDA\] : Compte rendu", qualifCr.RootNode.Criteria[0].Value);
            Assert.Equal(2, qualifCr.Actions.Count);
            Assert.Equal(ActionType.AddCategory, qualifCr.Actions[0].Type);
            Assert.Equal("DAMSI-DA-QUALIF CEDA", qualifCr.Actions[0].Parameter);
            Assert.Equal(ActionType.SetImportance, qualifCr.Actions[1].Type);
            Assert.Equal("Normale", qualifCr.Actions[1].Parameter);

            // 3. Transport - À revoir
            var transportARevoir = rules.Single(r => r.Name == "Transport - À revoir");
            Assert.Single(transportARevoir.RootNode.Criteria);
            Assert.Equal("A revoir|Modification billet", transportARevoir.RootNode.Criteria[0].Value);
            Assert.Single(transportARevoir.Actions);
            Assert.Equal(ActionType.AddCategory, transportARevoir.Actions[0].Type);
            Assert.Equal("Transport Hotels", transportARevoir.Actions[0].Parameter);

            // 4. Transport - Mots-clés Sujet
            var transportSujet = rules.Single(r => r.Name == "Transport - Mots-clés Sujet");
            Assert.Single(transportSujet.RootNode.Criteria);
            Assert.Equal("SNCF|Train|Billet", transportSujet.RootNode.Criteria[0].Value);
            Assert.Single(transportSujet.Actions);
            Assert.Equal(ActionType.AddCategory, transportSujet.Actions[0].Type);
            Assert.Equal("Transport Hotels", transportSujet.Actions[0].Parameter);

            // 5. Transport Hotels - Confirmation réservation (Expéditeur + Sujet)
            var hotelConfirm = rules.Single(r => r.Name == "Transport Hotels - Confirmation réservation");
            Assert.Equal(LogicalOperator.And, hotelConfirm.RootNode.Operator);
            Assert.Equal(2, hotelConfirm.RootNode.Criteria.Count);
            Assert.Contains(hotelConfirm.RootNode.Criteria, c => c.Field == MailField.Sender && c.Operator == MatchOperator.Contains && c.Value == "ucanss@ailleursbusiness.com");
            Assert.Contains(hotelConfirm.RootNode.Criteria, c => c.Field == MailField.Subject && c.Operator == MatchOperator.Contains && c.Value == "Confirmation de votre réservation hôtel");
            Assert.Single(hotelConfirm.Actions);
            Assert.Equal(ActionType.AddCategory, hotelConfirm.Actions[0].Type);
            Assert.Equal("Transport Hotels", hotelConfirm.Actions[0].Parameter);

            // 6. CCOEN - La Fleuriaye (Expéditeur + Sujet)
            var fleuriaye = rules.Single(r => r.Name == "CCOEN - La Fleuriaye");
            Assert.Equal(LogicalOperator.And, fleuriaye.RootNode.Operator);
            Assert.Equal(2, fleuriaye.RootNode.Criteria.Count);
            Assert.Contains(fleuriaye.RootNode.Criteria, c => c.Field == MailField.Sender && c.Operator == MatchOperator.Contains && c.Value == "nathalie.ponsard@assurance-maladie.fr");
            Assert.Contains(fleuriaye.RootNode.Criteria, c => c.Field == MailField.Subject && c.Operator == MatchOperator.Contains && c.Value == "La Fleuriaye");
            Assert.Single(fleuriaye.Actions);
            Assert.Equal(ActionType.AddCategory, fleuriaye.Actions[0].Type);
            Assert.Equal("CCOEN-La Fleuriaye", fleuriaye.Actions[0].Parameter);

            // 7 à 13. Règles de déplacement par catégorie
            var moveSyndicats = rules.Single(r => r.Name == "Déplacement - Administratif-Syndicats");
            Assert.Equal("Administratif-Syndicats", moveSyndicats.RootNode.Criteria[0].Value);
            Assert.Equal(ActionType.MoveToFolder, moveSyndicats.Actions[0].Type);
            Assert.Equal("Syndicats", moveSyndicats.Actions[0].Parameter);

            var moveClearQuest = rules.Single(r => r.Name == "Déplacement - ClearQuest");
            Assert.Equal("ClearQuest CNAM", moveClearQuest.Actions[0].Parameter);

            var moveConfluence = rules.Single(r => r.Name == "Déplacement - Confluence");
            Assert.Equal("Confluence", moveConfluence.Actions[0].Parameter);

            var moveVeille = rules.Single(r => r.Name == "Déplacement - Urba-Veille");
            Assert.Equal("Veille", moveVeille.Actions[0].Parameter);

            var moveLettres = rules.Single(r => r.Name == "Déplacement - Comitologie-CNAM-Lettres Réseau");
            Assert.Equal("Lettres Réseau", moveLettres.Actions[0].Parameter);

            var moveFleuriaye = rules.Single(r => r.Name == "Déplacement - CCOEN-La Fleuriaye");
            Assert.Equal("La Fleuriaye", moveFleuriaye.Actions[0].Parameter);

            var moveHotels = rules.Single(r => r.Name == "Déplacement - Transport Hotels");
            Assert.Equal("Transport Hotels", moveHotels.Actions[0].Parameter);
        }
    }
